  const f=$('ux10-plan-form'),setContracts=()=>{f.elements.contract_id.innerHTML='<option value="">'+t('请选择','Select')+'</option>'+o.contracts.filter(k=>k.project_id===f.elements.project_id.value&&k.customer_id===f.elements.customer_id.value).map(k=>'<option value="'+k.id+'" '+(k.id===p.contract_id?'selected':'')+'>'+esc(k.contract_no)+'</option>').join('');},setProject=()=>{const project=f.elements.project_id.value;f.elements.customer_id.innerHTML='<option value="">'+t('请选择','Select')+'</option>'+o.customers.filter(c=>c.project_id===project&&(c.active||c.id===p.customer_id)).map(c=>'<option value="'+c.id+'" '+(c.id===p.customer_id?'selected':'')+'>'+esc(c.name)+'</option>').join('');if(co&&f.elements.warehouse_id)f.elements.warehouse_id.innerHTML=o.warehouses.filter(w=>w.project_id===project).map(w=>'<option value="'+w.id+'" '+(w.id===p.warehouse_id?'selected':'')+'>'+esc(I18n.translate(w.name,true))+'</option>').join('');setContracts();};setProject();f.elements.project_id.onchange=setProject;f.elements.customer_id.onchange=setContracts;
